import { Router } from 'express';
import bcrypt from 'bcryptjs';
import { createHash, timingSafeEqual } from 'node:crypto';
import { getPool, sql } from './db.js';
import { signToken } from './auth.js';

const router = Router();
const roleIn = { admin: 'quan tri vien', teacher: 'giang vien', student: 'hoc vien' };
const roleOut = Object.fromEntries(Object.entries(roleIn).map(([a, b]) => [b, a]));
const userStatusIn = { active: 'dang hoat dong', inactive: 'ngung hoat dong', banned: 'bi khoa', deleted: 'da xoa' };
const userStatusOut = Object.fromEntries(Object.entries(userStatusIn).map(([a, b]) => [b, a]));
const courseStatusIn = { draft: 'nhap', published: 'da xuat ban', archived: 'da luu tru' };
const courseStatusOut = Object.fromEntries(Object.entries(courseStatusIn).map(([a, b]) => [b, a]));
const classStatusIn = { upcoming: 'sap dien ra', ongoing: 'dang dien ra', completed: 'da hoan thanh', cancelled: 'da huy' };
const classStatusOut = Object.fromEntries(Object.entries(classStatusIn).map(([a, b]) => [b, a]));
const orderStatusOut = { 'cho thanh toan': 'pending', 'da thanh toan': 'paid', 'that bai': 'failed', 'da huy': 'cancelled', 'hoan tien mot phan': 'partial_refunded', 'da hoan tien': 'refunded' };
const fail = (status, code, message) => Object.assign(new Error(message), { status, code });
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const paramId = (req) => {
  if (!uuid.test(req.params.id || '')) throw fail(400, 'INVALID_ID', 'ID không hợp lệ.');
  return req.params.id;
};
const paging = (req) => ({ page: Math.max(1, Number.parseInt(req.query.page, 10) || 1), limit: Math.min(100, Math.max(1, Number.parseInt(req.query.limit, 10) || 20)) });
const list = async (req, res, query, mapper = (x) => x) => {
  const { page, limit } = paging(req); const pool = await getPool();
  const request = pool.request().input('offset', sql.Int, (page - 1) * limit).input('limit', sql.Int, limit);
  const result = await request.query(query);
  res.json({ data: result.recordset.map(mapper), pagination: { page, limit, total: result.recordset[0]?.total ?? 0 } });
};
const dateParam = (req, key, required = false) => {
  const value = req.body[key];
  if (!value && !required) return null;
  const date = new Date(value);
  if (!value || Number.isNaN(date.valueOf())) throw fail(400, 'VALIDATION_ERROR', `${key} không hợp lệ.`);
  return date;
};

router.post('/auth/login', async (req, res) => {
  const email = String(req.body.email || '').trim().toLowerCase();
  const password = String(req.body.password || '');
  if (!email || !password) throw fail(400, 'VALIDATION_ERROR', 'Cần nhập email và mật khẩu.');
  const pool = await getPool();
  const result = await pool.request().input('email', sql.NVarChar(150), email)
    .query(`SELECT id, ho_ten, email, mat_khau_hash, vai_tro, trang_thai FROM dbo.nguoi_dung WHERE email=@email AND trang_thai <> N'da xoa'`);
  const user = result.recordset[0];
  const storedHash = String(user?.mat_khau_hash || '');
  const isBcrypt = /^\$2[aby]\$/.test(storedHash);
  const legacyDigest = /^[a-f\d]{64}$/i.test(storedHash) ? Buffer.from(storedHash, 'hex') : null;
  const suppliedDigest = createHash('sha256').update(password, 'utf8').digest();
  const validLegacy = legacyDigest?.length === suppliedDigest.length && timingSafeEqual(legacyDigest, suppliedDigest);
  const validPassword = user && (isBcrypt ? await bcrypt.compare(password, storedHash) : Boolean(validLegacy));
  if (!validPassword) throw fail(401, 'INVALID_CREDENTIALS', 'Email hoặc mật khẩu không đúng.');
  if (!isBcrypt) {
    const upgradedHash = await bcrypt.hash(password, 12);
    await pool.request().input('id', sql.UniqueIdentifier, user.id).input('hash', sql.NVarChar(255), upgradedHash)
      .query('UPDATE dbo.nguoi_dung SET mat_khau_hash=@hash WHERE id=@id');
  }
  if (user.trang_thai !== 'dang hoat dong') throw fail(403, 'ACCOUNT_DISABLED', 'Tài khoản đang bị khóa hoặc ngừng hoạt động.');
  if (user.vai_tro !== 'quan tri vien') throw fail(403, 'ADMIN_REQUIRED', 'Tài khoản không có quyền quản trị.');
  await pool.request().input('id', sql.UniqueIdentifier, user.id).query('UPDATE dbo.nguoi_dung SET lan_dang_nhap_cuoi=SYSDATETIME() WHERE id=@id');
  res.json({ data: { token: signToken(user, Boolean(req.body.rememberMe)), user: { id: user.id, name: user.ho_ten, email: user.email, role: 'admin' } } });
});
router.post('/auth/logout', (_req, res) => res.json({ data: { loggedOut: true } }));
router.get('/auth/me', (req, res) => res.json({ data: req.user }));

router.get('/users', async (req, res) => {
  const { page, limit } = paging(req); const pool = await getPool();
  const q = pool.request().input('offset', sql.Int, (page - 1) * limit).input('limit', sql.Int, limit)
    .input('q', sql.NVarChar(200), `%${String(req.query.q || '').trim()}%`)
    .input('role', sql.NVarChar(20), roleIn[req.query.role] || null)
    .input('status', sql.NVarChar(20), userStatusIn[req.query.status] || null);
  const r = await q.query(`SELECT id,ho_ten,email,so_dien_thoai,anh_dai_dien,vai_tro,trang_thai,ngay_tao,lan_dang_nhap_cuoi,
    COUNT(*) OVER() total FROM dbo.nguoi_dung WHERE (ho_ten LIKE @q OR email LIKE @q) AND (@role IS NULL OR vai_tro=@role)
    AND (@status IS NULL OR trang_thai=@status) ORDER BY ngay_tao DESC OFFSET @offset ROWS FETCH NEXT @limit ROWS ONLY`);
  res.json({ data: r.recordset.map(x => ({ id:x.id,name:x.ho_ten,email:x.email,phone:x.so_dien_thoai||'',avatar:x.anh_dai_dien,role:roleOut[x.vai_tro],status:userStatusOut[x.trang_thai],createdAt:x.ngay_tao,lastLogin:x.lan_dang_nhap_cuoi,classes:[],orders:[] })), pagination:{page,limit,total:r.recordset[0]?.total||0} });
});
router.get('/users/:id', async (req,res) => {
  const id=paramId(req), pool=await getPool(); const r=await pool.request().input('id',sql.UniqueIdentifier,id).query(`SELECT id,ho_ten,email,so_dien_thoai,anh_dai_dien,vai_tro,trang_thai,ngay_tao,lan_dang_nhap_cuoi FROM dbo.nguoi_dung WHERE id=@id`);
  if(!r.recordset[0]) throw fail(404,'NOT_FOUND','Không tìm thấy người dùng.'); const x=r.recordset[0];
  res.json({data:{id:x.id,name:x.ho_ten,email:x.email,phone:x.so_dien_thoai||'',avatar:x.anh_dai_dien,role:roleOut[x.vai_tro],status:userStatusOut[x.trang_thai],createdAt:x.ngay_tao,lastLogin:x.lan_dang_nhap_cuoi,classes:[],orders:[]}});
});
router.post('/users', async (req,res) => {
  const {name,email,password,phone,avatar,role='student'}=req.body;
  if(!name?.trim()||!email?.trim()||String(password||'').length<10||!roleIn[role]) throw fail(400,'VALIDATION_ERROR','Họ tên, email hợp lệ, vai trò và mật khẩu tối thiểu 10 ký tự là bắt buộc.');
  const hash=await bcrypt.hash(password,12),pool=await getPool();
  const r=await pool.request().input('name',sql.NVarChar(100),name.trim()).input('email',sql.NVarChar(150),email.trim().toLowerCase()).input('hash',sql.NVarChar(255),hash).input('phone',sql.NVarChar(20),phone||null).input('avatar',sql.NVarChar(255),avatar||null).input('role',sql.NVarChar(20),roleIn[role]).query(`INSERT dbo.nguoi_dung(ho_ten,email,mat_khau_hash,so_dien_thoai,anh_dai_dien,vai_tro) OUTPUT inserted.id,inserted.ho_ten,inserted.email,inserted.so_dien_thoai,inserted.anh_dai_dien,inserted.vai_tro,inserted.trang_thai VALUES(@name,@email,@hash,@phone,@avatar,@role)`);
  const x=r.recordset[0];res.status(201).json({data:{id:x.id,name:x.ho_ten,email:x.email,phone:x.so_dien_thoai,role:roleOut[x.vai_tro],status:userStatusOut[x.trang_thai]}});
});
router.put('/users/:id', async(req,res)=>{
  const id=paramId(req),{name,email,phone,avatar,role}=req.body;
  if(!name?.trim()||!email?.trim()||(role&&!roleIn[role])) throw fail(400,'VALIDATION_ERROR','Họ tên, email và vai trò không hợp lệ.');
  const pool=await getPool(),r=await pool.request().input('id',sql.UniqueIdentifier,id).input('name',sql.NVarChar(100),name.trim()).input('email',sql.NVarChar(150),email.trim().toLowerCase()).input('phone',sql.NVarChar(20),phone||null).input('avatar',sql.NVarChar(255),avatar||null).input('role',sql.NVarChar(20),role?roleIn[role]:null).query(`UPDATE dbo.nguoi_dung SET ho_ten=@name,email=@email,so_dien_thoai=@phone,anh_dai_dien=@avatar,vai_tro=COALESCE(@role,vai_tro) OUTPUT inserted.id,inserted.ho_ten,inserted.email,inserted.so_dien_thoai,inserted.anh_dai_dien,inserted.vai_tro,inserted.trang_thai WHERE id=@id AND trang_thai<>N'da xoa'`);
  if(!r.recordset[0])throw fail(404,'NOT_FOUND','Không tìm thấy người dùng.');const x=r.recordset[0];res.json({data:{id:x.id,name:x.ho_ten,email:x.email,phone:x.so_dien_thoai,role:roleOut[x.vai_tro],status:userStatusOut[x.trang_thai]}});
});
router.patch('/users/:id/status',async(req,res)=>{
  const id=paramId(req),status=userStatusIn[req.body.status];if(!status)throw fail(400,'VALIDATION_ERROR','Trạng thái không hợp lệ.');
  const pool=await getPool(),r=await pool.request().input('id',sql.UniqueIdentifier,id).input('status',sql.NVarChar(20),status).query(`UPDATE dbo.nguoi_dung SET trang_thai=@status OUTPUT inserted.id,inserted.trang_thai WHERE id=@id`);
  if(!r.recordset[0])throw fail(404,'NOT_FOUND','Không tìm thấy người dùng.');res.json({data:{id:r.recordset[0].id,status:userStatusOut[r.recordset[0].trang_thai]}});
});
router.delete('/users/:id',async(req,res)=>{const id=paramId(req),pool=await getPool();const r=await pool.request().input('id',sql.UniqueIdentifier,id).query(`UPDATE dbo.nguoi_dung SET trang_thai=N'da xoa' WHERE id=@id AND vai_tro<>N'quan tri vien' AND trang_thai<>N'da xoa'; SELECT @@ROWCOUNT affected`);if(!r.recordset[0]?.affected)throw fail(404,'NOT_FOUND','Không tìm thấy người dùng hoặc không thể xóa tài khoản quản trị.');res.status(204).end();});
router.post('/users/bulk-action',async(req,res)=>{
  const {ids,action}=req.body;if(!Array.isArray(ids)||!ids.length||ids.length>200||ids.some(id=>!uuid.test(id)))throw fail(400,'VALIDATION_ERROR','Danh sách ID không hợp lệ.');
  const status={activate:'dang hoat dong',deactivate:'ngung hoat dong',ban:'bi khoa',delete:'da xoa'}[action];if(!status)throw fail(400,'VALIDATION_ERROR','Thao tác không hợp lệ.');
  const pool=await getPool(),tx=new sql.Transaction(pool);await tx.begin();try{const q=new sql.Request(tx).input('status',sql.NVarChar(20),status);ids.forEach((id,i)=>q.input(`id${i}`,sql.UniqueIdentifier,id));const inList=ids.map((_,i)=>`@id${i}`).join(',');const r=await q.query(`UPDATE dbo.nguoi_dung SET trang_thai=@status WHERE id IN (${inList}) AND vai_tro<>N'quan tri vien'; SELECT @@ROWCOUNT affected`);await tx.commit();res.json({data:{updated:r.recordset[0].affected}});}catch(e){await tx.rollback();throw e;}
});

router.get('/categories', async(req,res)=>list(req,res,`SELECT d.id,d.ten_danh_muc,d.ngay_tao,(SELECT COUNT(*) FROM dbo.khoa_hoc k WHERE k.danh_muc_id=d.id) course_count,COUNT(*) OVER() total FROM dbo.danh_muc_khoa_hoc d ORDER BY d.ten_danh_muc OFFSET @offset ROWS FETCH NEXT @limit ROWS ONLY`,x=>({id:x.id,name:x.ten_danh_muc,courseCount:x.course_count,createdAt:x.ngay_tao,description:''})));
router.post('/categories',async(req,res)=>{const name=String(req.body.name||'').trim();if(!name||name.length>100)throw fail(400,'VALIDATION_ERROR','Tên danh mục bắt buộc (tối đa 100 ký tự).');const p=await getPool(),r=await p.request().input('name',sql.NVarChar(100),name).query('INSERT dbo.danh_muc_khoa_hoc(ten_danh_muc) OUTPUT inserted.id,inserted.ten_danh_muc VALUES(@name)');res.status(201).json({data:{id:r.recordset[0].id,name:r.recordset[0].ten_danh_muc}});});
router.put('/categories/:id',async(req,res)=>{const id=paramId(req),name=String(req.body.name||'').trim();if(!name||name.length>100)throw fail(400,'VALIDATION_ERROR','Tên danh mục bắt buộc.');const p=await getPool(),r=await p.request().input('id',sql.UniqueIdentifier,id).input('name',sql.NVarChar(100),name).query('UPDATE dbo.danh_muc_khoa_hoc SET ten_danh_muc=@name OUTPUT inserted.id,inserted.ten_danh_muc WHERE id=@id');if(!r.recordset[0])throw fail(404,'NOT_FOUND','Không tìm thấy danh mục.');res.json({data:{id:r.recordset[0].id,name:r.recordset[0].ten_danh_muc}});});
router.delete('/categories/:id',async(req,res)=>{const id=paramId(req),p=await getPool();try{const r=await p.request().input('id',sql.UniqueIdentifier,id).query('DELETE dbo.danh_muc_khoa_hoc WHERE id=@id; SELECT @@ROWCOUNT affected');if(!r.recordset[0]?.affected)throw fail(404,'NOT_FOUND','Không tìm thấy danh mục.');res.status(204).end();}catch(e){if(e.number===547)throw fail(409,'IN_USE','Danh mục đang được khóa học sử dụng.');throw e;}});

router.get('/courses', async(req,res)=>{
  const {page,limit}=paging(req),p=await getPool(),q=p.request().input('offset',sql.Int,(page-1)*limit).input('limit',sql.Int,limit).input('search',sql.NVarChar(200),`%${String(req.query.q||'').trim()}%`).input('status',sql.NVarChar(20),courseStatusIn[req.query.status]||null).input('category',sql.NVarChar(100),req.query.category||null).input('level',sql.NVarChar(20),{beginner:'co ban',intermediate:'trung cap',advanced:'nang cao'}[req.query.level]||null).input('exam',sql.NVarChar(20),req.query.exam?req.query.exam==='none'?'khong ap dung':req.query.exam:null).input('moderation',sql.NVarChar(20),{pending:'cho duyet',approved:'da duyet',rejected:'tu choi'}[req.query.moderation]||null).input('visible',sql.Bit,req.query.visibility==='visible'?1:req.query.visibility==='hidden'?0:null);
  const r=await q.query(`SELECT k.id,k.ten_khoa_hoc,k.danh_muc_id,k.mo_ta,k.trinh_do,k.trang_thai,k.loai_ky_thi,k.gia,k.ngay_tao,k.anh_dai_dien,k.trinh_do_dau_vao,k.diem_muc_tieu,k.hinh_thuc,k.thoi_luong_gio,k.so_ngay_truy_cap,k.hien_thi,k.trang_thai_duyet,d.ten_danh_muc,nd.ho_ten ten_giang_vien,(SELECT COUNT(*) FROM dbo.dang_ky_khoa_hoc dk WHERE dk.ma_khoa_hoc=k.id) so_hoc_vien,COUNT(*) OVER() total FROM dbo.khoa_hoc k JOIN dbo.danh_muc_khoa_hoc d ON d.id=k.danh_muc_id JOIN dbo.nguoi_dung nd ON nd.id=k.nguoi_tao_id WHERE (k.ten_khoa_hoc LIKE @search OR nd.ho_ten LIKE @search) AND (@status IS NULL OR k.trang_thai=@status) AND (@category IS NULL OR d.ten_danh_muc=@category) AND (@level IS NULL OR k.trinh_do=@level) AND (@exam IS NULL OR k.loai_ky_thi=@exam) AND (@moderation IS NULL OR k.trang_thai_duyet=@moderation) AND (@visible IS NULL OR k.hien_thi=@visible) ORDER BY k.ngay_tao DESC OFFSET @offset ROWS FETCH NEXT @limit ROWS ONLY`);
  res.json({data:r.recordset.map(x=>({id:x.id,title:x.ten_khoa_hoc,description:x.mo_ta,categoryId:x.danh_muc_id,level:{'co ban':'beginner','trung cap':'intermediate','nang cao':'advanced'}[x.trinh_do],status:courseStatusOut[x.trang_thai],examType:x.loai_ky_thi==='khong ap dung'?'none':x.loai_ky_thi,price:x.gia,category:x.ten_danh_muc,teacherName:x.ten_giang_vien,creator:x.ten_giang_vien,studentsCount:x.so_hoc_vien,enrolledCount:x.so_hoc_vien,createdAt:x.ngay_tao,thumbnailUrl:x.anh_dai_dien,entryLevel:x.trinh_do_dau_vao,targetScore:x.diem_muc_tieu,format:x.hinh_thuc==='co lop'?'with_class':'self_study',durationHours:x.thoi_luong_gio,accessDays:x.so_ngay_truy_cap,isVisible:x.hien_thi,moderationStatus:{'cho duyet':'pending','da duyet':'approved','tu choi':'rejected'}[x.trang_thai_duyet]})),pagination:{page,limit,total:r.recordset[0]?.total||0}});
});
router.get('/courses/:id',async(req,res)=>{const id=paramId(req),p=await getPool(),r=await p.request().input('id',sql.UniqueIdentifier,id).query(`SELECT k.*,d.ten_danh_muc,nd.ho_ten ten_giang_vien FROM dbo.khoa_hoc k JOIN dbo.danh_muc_khoa_hoc d ON d.id=k.danh_muc_id JOIN dbo.nguoi_dung nd ON nd.id=k.nguoi_tao_id WHERE k.id=@id`);if(!r.recordset[0])throw fail(404,'NOT_FOUND','Không tìm thấy khóa học.');const x=r.recordset[0];res.json({data:{id:x.id,title:x.ten_khoa_hoc,description:x.mo_ta,category:x.ten_danh_muc,categoryId:x.danh_muc_id,level:{'co ban':'beginner','trung cap':'intermediate','nang cao':'advanced'}[x.trinh_do],examType:x.loai_ky_thi==='khong ap dung'?'none':x.loai_ky_thi,status:courseStatusOut[x.trang_thai],price:x.gia,teacherName:x.ten_giang_vien,thumbnailUrl:x.anh_dai_dien,entryLevel:x.trinh_do_dau_vao,targetScore:x.diem_muc_tieu,format:x.hinh_thuc==='co lop'?'with_class':'self_study',durationHours:x.thoi_luong_gio,accessDays:x.so_ngay_truy_cap,isVisible:x.hien_thi,moderationStatus:{'cho duyet':'pending','da duyet':'approved','tu choi':'rejected'}[x.trang_thai_duyet]}});});
router.post('/courses',async(req,res)=>{const b=req.body,{title,description,categoryId,level='beginner',price}=b,exam=b.examType||b.exam||'none';const levels={beginner:'co ban',intermediate:'trung cap',advanced:'nang cao'};const mods={pending:'cho duyet',approved:'da duyet',rejected:'tu choi'};if(!title?.trim()||!uuid.test(categoryId||'')||!levels[level]||!['TOEIC','IELTS','none'].includes(exam)|| (price!==null&&price!==undefined&&(!Number.isFinite(Number(price))||Number(price)<0))||(b.isVisible&&price==null))throw fail(400,'VALIDATION_ERROR','Thông tin khóa học không hợp lệ.');const p=await getPool(),r=await p.request().input('title',sql.NVarChar(200),title.trim()).input('desc',sql.NVarChar(sql.MAX),description||null).input('cat',sql.UniqueIdentifier,categoryId).input('level',sql.NVarChar(20),levels[level]).input('exam',sql.NVarChar(20),exam==='none'?'khong ap dung':exam).input('price',sql.Decimal(12,2),price===undefined?null:price).input('admin',sql.UniqueIdentifier,req.user.id).input('image',sql.NVarChar(500),b.thumbnailUrl||null).input('entry',sql.NVarChar(100),b.entryLevel||null).input('score',sql.Decimal(5,2),b.targetScore??null).input('format',sql.NVarChar(20),b.format==='with_class'?'co lop':'tu hoc').input('duration',sql.Decimal(7,2),b.durationHours??null).input('days',sql.Int,b.accessDays??null).input('visible',sql.Bit,Boolean(b.isVisible)).input('moderation',sql.NVarChar(20),mods[b.moderationStatus]||'cho duyet').input('status',sql.NVarChar(20),courseStatusIn[b.status]||'nhap').query(`INSERT dbo.khoa_hoc(ten_khoa_hoc,mo_ta,danh_muc_id,trinh_do,loai_ky_thi,gia,nguoi_tao_id,anh_dai_dien,trinh_do_dau_vao,diem_muc_tieu,hinh_thuc,thoi_luong_gio,so_ngay_truy_cap,hien_thi,trang_thai_duyet,trang_thai) OUTPUT inserted.id,inserted.ten_khoa_hoc,inserted.trang_thai VALUES(@title,@desc,@cat,@level,@exam,@price,@admin,@image,@entry,@score,@format,@duration,@days,@visible,@moderation,@status)`);res.status(201).json({data:{id:r.recordset[0].id,title:r.recordset[0].ten_khoa_hoc,status:courseStatusOut[r.recordset[0].trang_thai]}});});
