router.post('/payment-gateways',async(req,res)=>{const{name,feePercent=0,isActive=true}=req.body;if(!name?.trim()||Number(feePercent)<0||Number(feePercent)>100)throw fail(400,'VALIDATION_ERROR','Tên cổng và phí 0–100% hợp lệ là bắt buộc.');const p=await getPool(),r=await p.request().input('name',sql.NVarChar(100),name.trim()).input('fee',sql.Decimal(7,4),feePercent).input('active',sql.Bit,isActive).query('INSERT dbo.cong_thanh_toan(ten_cong,phi_giao_dich,kich_hoat) OUTPUT inserted.ma_cong VALUES(@name,@fee,@active)');res.status(201).json({data:{id:r.recordset[0].ma_cong,name,code:name}});});
router.put('/payment-gateways/:id',async(req,res)=>{const id=paramId(req),{name,feePercent,isActive}=req.body;if(!name?.trim()||Number(feePercent)<0||Number(feePercent)>100)throw fail(400,'VALIDATION_ERROR','Thông tin cổng thanh toán không hợp lệ.');const p=await getPool(),r=await p.request().input('id',sql.UniqueIdentifier,id).input('name',sql.NVarChar(100),name.trim()).input('fee',sql.Decimal(7,4),feePercent).input('active',sql.Bit,isActive).query('UPDATE dbo.cong_thanh_toan SET ten_cong=@name,phi_giao_dich=@fee,kich_hoat=@active WHERE ma_cong=@id; SELECT @@ROWCOUNT affected');if(!r.recordset[0]?.affected)throw fail(404,'NOT_FOUND','Không tìm thấy cổng thanh toán.');res.json({data:{id}});});
router.patch('/payment-gateways/:id/toggle',async(req,res)=>{const id=paramId(req),p=await getPool(),r=await p.request().input('id',sql.UniqueIdentifier,id).query('UPDATE dbo.cong_thanh_toan SET kich_hoat=1-kich_hoat OUTPUT inserted.kich_hoat WHERE ma_cong=@id');if(!r.recordset[0])throw fail(404,'NOT_FOUND','Không tìm thấy cổng thanh toán.');res.json({data:{id,isActive:r.recordset[0].kich_hoat}});});

router.get('/refunds',async(req,res)=>list(req,res,`SELECT ht.ma_yeu_cau,ht.ma_thanh_toan,ht.ly_do,ht.so_tien_hoan,ht.trang_thai,ht.ngay_yeu_cau,ht.ngay_xu_ly,nd.ho_ten,nd.email,dh.ma_don_hang,kh.ten_khoa_hoc,COUNT(*) OVER() total FROM dbo.yeu_cau_hoan_tien ht JOIN dbo.nguoi_dung nd ON nd.id=ht.ma_hoc_vien JOIN dbo.thanh_toan t ON t.ma_thanh_toan=ht.ma_thanh_toan JOIN dbo.don_hang dh ON dh.ma_don_hang=t.ma_don_hang OUTER APPLY(SELECT TOP 1 k.ten_khoa_hoc FROM dbo.chi_tiet_don_hang ct JOIN dbo.khoa_hoc k ON k.id=ct.ma_khoa_hoc WHERE ct.ma_don_hang=dh.ma_don_hang) kh ORDER BY ht.ngay_yeu_cau DESC OFFSET @offset ROWS FETCH NEXT @limit ROWS ONLY`,x=>({id:x.ma_yeu_cau,paymentId:x.ma_thanh_toan,orderId:x.ma_don_hang,reason:x.ly_do,courseName:x.ten_khoa_hoc||'—',amount:x.so_tien_hoan,refundAmount:x.so_tien_hoan,status:{'cho xu ly':'pending','da chap nhan':'approved','tu choi':'rejected','da hoan tien':'refunded'}[x.trang_thai],createdAt:x.ngay_yeu_cau,requestDate:x.ngay_yeu_cau,processedDate:x.ngay_xu_ly,user:x.ho_ten,userEmail:x.email,email:x.email,bankAccount:'—'})));
const handleRefund = action => async(req,res)=>{
  const id=paramId(req),map={approve:'da chap nhan',reject:'tu choi',complete:'da hoan tien'},status=map[action];
  const reason=String(req.body.reason||'').trim();
  if(action==='reject'&&!reason)throw fail(400,'VALIDATION_ERROR','Cần ghi lý do từ chối.');
  const p=await getPool(),tx=new sql.Transaction(p);await tx.begin();
  try {
    const q=new sql.Request(tx).input('id',sql.UniqueIdentifier,id).input('status',sql.NVarChar(20),status).input('admin',sql.UniqueIdentifier,req.user.id);
    const r=await q.query(`UPDATE dbo.yeu_cau_hoan_tien SET trang_thai=@status,ma_admin_xu_ly=@admin,ngay_xu_ly=SYSDATETIME() WHERE ma_yeu_cau=@id AND ((@status IN (N'da chap nhan',N'tu choi') AND trang_thai=N'cho xu ly') OR (@status=N'da hoan tien' AND trang_thai=N'da chap nhan')); SELECT ma_thanh_toan FROM dbo.yeu_cau_hoan_tien WHERE ma_yeu_cau=@id AND trang_thai=@status`);
    if(!r.recordset[0]?.ma_thanh_toan)throw fail(409,'INVALID_STATE','Yêu cầu hoàn tiền không ở trạng thái phù hợp.');
    if(action==='complete')await new sql.Request(tx).input('payment',sql.UniqueIdentifier,r.recordset[0].ma_thanh_toan).query(`
      UPDATE dh SET trang_thai=CASE WHEN COALESCE((SELECT SUM(ht.so_tien_hoan) FROM dbo.yeu_cau_hoan_tien ht JOIN dbo.thanh_toan tp ON tp.ma_thanh_toan=ht.ma_thanh_toan WHERE tp.ma_don_hang=dh.ma_don_hang AND ht.trang_thai=N'da hoan tien'),0)>=dh.so_tien_phai_tra THEN N'da hoan tien' ELSE N'hoan tien mot phan' END 
      FROM dbo.don_hang dh JOIN dbo.thanh_toan t ON t.ma_don_hang=dh.ma_don_hang WHERE t.ma_thanh_toan=@payment;

      UPDATE dk SET trang_thai=N'da huy'
      FROM dbo.dang_ky_khoa_hoc dk
      JOIN dbo.thanh_toan t ON t.ma_don_hang=dk.ma_don_hang
      JOIN dbo.don_hang dh ON dh.ma_don_hang=t.ma_don_hang
      WHERE t.ma_thanh_toan=@payment AND dh.trang_thai=N'da hoan tien';
    `);
    await tx.commit();res.json({data:{id,status:action}});
  } catch(e) { await tx.rollback();throw e; }
};router.post('/refunds/:id/approve',handleRefund('approve'));
router.post('/refunds/:id/reject',handleRefund('reject'));
router.post('/refunds/:id/complete',handleRefund('complete'));

router.get('/tickets',async(req,res)=>list(req,res,`SELECT yc.id,yc.tieu_de,yc.danh_muc,yc.trang_thai,yc.do_uu_tien,yc.ngay_tao,yc.ngay_cap_nhat,nd.ho_ten,nd.email,COUNT(*) OVER() total FROM dbo.yeu_cau_ho_tro yc JOIN dbo.nguoi_dung nd ON nd.id=yc.nguoi_dung_id ORDER BY yc.ngay_tao DESC OFFSET @offset ROWS FETCH NEXT @limit ROWS ONLY`,x=>({id:x.id,title:x.tieu_de,sender:{name:x.ho_ten,email:x.email},category:{'ky thuat':'technical','tai khoan':'account','khoa hoc':'course','khac':'other'}[x.danh_muc],priority:{thap:'low','trung binh':'medium',cao:'high'}[x.do_uu_tien],status:{moi:'new','dang xu ly':'in_progress','da xu ly':'resolved','da dong':'closed'}[x.trang_thai],createdAt:x.ngay_tao,updatedAt:x.ngay_cap_nhat})));
router.patch('/tickets/:id',async(req,res)=>{const id=paramId(req),statuses={new:'moi',in_progress:'dang xu ly',resolved:'da xu ly',closed:'da dong'},priorities={low:'thap',medium:'trung binh',high:'cao'},status=statuses[req.body.status],priority=priorities[req.body.priority];if(!status&&!priority)throw fail(400,'VALIDATION_ERROR','Trạng thái hoặc mức ưu tiên không hợp lệ.');const p=await getPool(),r=await p.request().input('id',sql.UniqueIdentifier,id).input('status',sql.NVarChar(20),status||null).input('priority',sql.NVarChar(20),priority||null).query(`UPDATE dbo.yeu_cau_ho_tro SET trang_thai=COALESCE(@status,trang_thai),do_uu_tien=COALESCE(@priority,do_uu_tien),ngay_xu_ly_xong=CASE WHEN COALESCE(@status,trang_thai) IN (N'da xu ly',N'da dong') THEN COALESCE(ngay_xu_ly_xong,SYSDATETIME()) ELSE NULL END WHERE id=@id; SELECT @@ROWCOUNT affected`);if(!r.recordset[0]?.affected)throw fail(404,'NOT_FOUND','Không tìm thấy yêu cầu hỗ trợ.');res.json({data:{id,status:req.body.status,priority:req.body.priority}});});
router.get('/tickets/:id/replies',async(req,res)=>{const id=paramId(req),p=await getPool(),r=await p.request().input('id',sql.UniqueIdentifier,id).query(`SELECT f.id,f.noi_dung,f.ngay_gui,n.ho_ten,n.id nguoi_gui_id FROM dbo.phan_hoi_ho_tro f JOIN dbo.nguoi_dung n ON n.id=f.nguoi_gui_id WHERE f.yeu_cau_id=@id ORDER BY f.ngay_gui`);res.json({data:r.recordset.map(x=>({id:x.id,content:x.noi_dung,sender:x.ho_ten,isAdmin:x.nguoi_gui_id===req.user.id,createdAt:x.ngay_gui}))});});
router.post('/tickets/:id/reply',async(req,res)=>{const id=paramId(req),content=String(req.body.content||'').trim();if(!content)throw fail(400,'VALIDATION_ERROR','Nội dung phản hồi không được để trống.');const p=await getPool(),r=await p.request().input('id',sql.UniqueIdentifier,id).input('admin',sql.UniqueIdentifier,req.user.id).input('content',sql.NVarChar(sql.MAX),content).query(`INSERT dbo.phan_hoi_ho_tro(yeu_cau_id,nguoi_gui_id,noi_dung) OUTPUT inserted.id,inserted.ngay_gui VALUES(@id,@admin,@content)`);res.status(201).json({data:{id:r.recordset[0].id,content,createdAt:r.recordset[0].ngay_gui}});});

router.get('/certificates',async(req,res)=>list(req,res,`SELECT cc.id,cc.ma_dang_ky,cc.so_chung_chi,cc.ngay_cap,cc.ngay_het_han,cc.trang_thai,nd.ho_ten,nd.email,nd.anh_dai_dien,k.ten_khoa_hoc,k.loai_ky_thi,COUNT(*) OVER() total FROM dbo.chung_chi cc JOIN dbo.dang_ky_khoa_hoc dk ON dk.ma_dang_ky=cc.ma_dang_ky JOIN dbo.nguoi_dung nd ON nd.id=dk.ma_hoc_vien JOIN dbo.khoa_hoc k ON k.id=dk.ma_khoa_hoc ORDER BY cc.ngay_cap DESC OFFSET @offset ROWS FETCH NEXT @limit ROWS ONLY`,x=>({id:x.id,enrollmentId:x.ma_dang_ky,certificateNumber:x.so_chung_chi,student:{name:x.ho_ten,email:x.email,avatar:x.anh_dai_dien},courseName:x.ten_khoa_hoc,courseCategory:x.loai_ky_thi,issueDate:x.ngay_cap,expiryDate:x.ngay_het_han,status:{'hop le':'valid','het han':'expired','bi thu hoi':'revoked'}[x.trang_thai]})));
router.post('/certificates',async(req,res)=>{const {enrollmentId,number,certificateNumber,expiresAt}=req.body,serial=number||certificateNumber;if(!uuid.test(enrollmentId||'')||!serial?.trim())throw fail(400,'VALIDATION_ERROR','Cần mã ghi danh và số chứng chỉ.');const p=await getPool(),eligible=await p.request().input('enrollment',sql.UniqueIdentifier,enrollmentId).query(`SELECT ma_dang_ky FROM dbo.dang_ky_khoa_hoc WHERE ma_dang_ky=@enrollment AND trang_thai=N'hoan thanh'`);if(!eligible.recordset[0])throw fail(409,'NOT_ELIGIBLE','Chỉ ghi danh đã hoàn thành mới được cấp chứng chỉ.');const r=await p.request().input('enrollment',sql.UniqueIdentifier,enrollmentId).input('number',sql.NVarChar(50),serial.trim()).input('expires',sql.DateTime2,dateParam(req,'expiresAt')).query(`INSERT dbo.chung_chi(ma_dang_ky,so_chung_chi,ngay_het_han) OUTPUT inserted.id,inserted.so_chung_chi VALUES(@enrollment,@number,@expires)`);res.status(201).json({data:{id:r.recordset[0].id,certificateNumber:r.recordset[0].so_chung_chi,status:'valid'}});});
router.patch('/certificates/:id/revoke',async(req,res)=>{const id=paramId(req),p=await getPool(),r=await p.request().input('id',sql.UniqueIdentifier,id).query(`UPDATE dbo.chung_chi SET trang_thai=N'bi thu hoi' OUTPUT inserted.id WHERE id=@id AND trang_thai=N'hop le'`);if(!r.recordset[0])throw fail(404,'NOT_FOUND','Không tìm thấy chứng chỉ đang hiệu lực.');res.json({data:{id,status:'revoked'}});});
router.get('/reviews/stats',async(_req,res)=>{const p=await getPool(),r=await p.request().query(`SELECT so_sao,COUNT(*) count FROM dbo.danh_gia_khoa_hoc GROUP BY so_sao`),total=r.recordset.reduce((sum,x)=>sum+x.count,0),average=total?r.recordset.reduce((sum,x)=>sum+x.so_sao*x.count,0)/total:0;res.json({data:{average:Number(average.toFixed(1)),total,distribution:Object.fromEntries([1,2,3,4,5].map(star=>[star,r.recordset.find(x=>x.so_sao===star)?.count||0]))}});});
