router.post('/notifications/broadcast',async(req,res)=>{const {title,content,recipient='all'}=req.body;if(!title?.trim())throw fail(400,'VALIDATION_ERROR','Tiêu đề là bắt buộc.');const p=await getPool(),r=await p.request().input('title',sql.NVarChar(200),title.trim()).input('content',sql.NVarChar(sql.MAX),content||null).input('role',sql.NVarChar(20),roleIn[recipient]||null).query(`INSERT dbo.thong_bao(nguoi_dung_id,tieu_de,noi_dung) SELECT id,@title,@content FROM dbo.nguoi_dung WHERE trang_thai=N'dang hoat dong' AND (@role IS NULL OR vai_tro=@role); SELECT @@ROWCOUNT affected`);res.status(201).json({data:{sent:r.recordset[0].affected}});});

