router.put('/profile/change-password',async(req,res)=>{const{currentPassword,newPassword}=req.body;if(!currentPassword||String(newPassword||'').length<10)throw fail(400,'VALIDATION_ERROR','Mật khẩu mới cần ít nhất 10 ký tự.');const p=await getPool(),r=await p.request().input('id',sql.UniqueIdentifier,req.user.id).query('SELECT mat_khau_hash FROM dbo.nguoi_dung WHERE id=@id'),oldHash=String(r.recordset[0]?.mat_khau_hash||'');let isValid=false;if(/^\$2[aby]\$/.test(oldHash))isValid=await bcrypt.compare(currentPassword,oldHash);else if(/^[a-f\d]{64}$/i.test(oldHash)){const a=Buffer.from(oldHash,'hex'),b=createHash('sha256').update(currentPassword,'utf8').digest();isValid=a.length===b.length&&timingSafeEqual(a,b);}if(!isValid)throw fail(400,'INVALID_PASSWORD','Mật khẩu hiện tại không đúng.');const hash=await bcrypt.hash(newPassword,12);await p.request().input('id',sql.UniqueIdentifier,req.user.id).input('hash',sql.NVarChar(255),hash).query('UPDATE dbo.nguoi_dung SET mat_khau_hash=@hash WHERE id=@id');res.json({data:{changed:true}});});

router.get('/dashboard/stats',async(_req,res)=>{const p=await getPool(),r=await p.request().query(`SELECT (SELECT COUNT(*) FROM dbo.nguoi_dung WHERE trang_thai<>N'da xoa') totalUsers,(SELECT COUNT(*) FROM dbo.khoa_hoc WHERE trang_thai=N'da xuat ban') publishedCourses,(SELECT COALESCE(SUM(so_tien_phai_tra),0) FROM dbo.don_hang WHERE trang_thai=N'da thanh toan' AND ngay_tao>=DATEFROMPARTS(YEAR(GETDATE()),MONTH(GETDATE()),1)) revenue,(SELECT COUNT(*) FROM dbo.yeu_cau_ho_tro WHERE trang_thai IN (N'moi',N'dang xu ly')) openTickets`);const x=r.recordset[0];res.json({data:[{id:'total_users',label:'Tổng người dùng',value:Number(x.totalUsers).toLocaleString('vi-VN'),icon:'Users',color:'indigo'},{id:'published_courses',label:'Khóa học đã xuất bản',value:Number(x.publishedCourses).toLocaleString('vi-VN'),icon:'BookOpen',color:'blue'},{id:'monthly_revenue',label:'Doanh thu tháng (VNĐ)',value:`${Number(x.revenue).toLocaleString('vi-VN')} ₫`,icon:'TrendingUp',color:'green'},{id:'pending_tickets',label:'Yêu cầu hỗ trợ chưa xử lý',value:Number(x.openTickets).toLocaleString('vi-VN'),icon:'HelpCircle',color:'red',invertTrend:true}]});});
router.get('/dashboard/revenue-chart',async(req,res)=>{const months=Math.min(24,Math.max(1,Number.parseInt(req.query.months,10)||12)),p=await getPool();const r=await p.request().input('months',sql.Int,months).query(`WITH m AS(SELECT DATEADD(MONTH,1-@months,DATEFROMPARTS(YEAR(GETDATE()),MONTH(GETDATE()),1)) d UNION ALL SELECT DATEADD(MONTH,1,d) FROM m WHERE d<DATEFROMPARTS(YEAR(GETDATE()),MONTH(GETDATE()),1)) SELECT CONCAT('T',MONTH(m.d)) month,COALESCE(SUM(CASE WHEN dh.trang_thai=N'da thanh toan' THEN dh.so_tien_phai_tra ELSE 0 END),0) revenue FROM m LEFT JOIN dbo.don_hang dh ON dh.ngay_tao>=m.d AND dh.ngay_tao<DATEADD(MONTH,1,m.d) GROUP BY m.d ORDER BY m.d OPTION(MAXRECURSION 24)`);res.json({data:r.recordset});});
router.get('/dashboard/enrollment-chart',async(req,res)=>{const months=Math.min(24,Math.max(1,Number.parseInt(req.query.months,10)||12)),p=await getPool();const r=await p.request().input('months',sql.Int,months).query(`WITH m AS(SELECT DATEADD(MONTH,1-@months,DATEFROMPARTS(YEAR(GETDATE()),MONTH(GETDATE()),1)) d UNION ALL SELECT DATEADD(MONTH,1,d) FROM m WHERE d<DATEFROMPARTS(YEAR(GETDATE()),MONTH(GETDATE()),1)) SELECT CONCAT('T',MONTH(m.d)) month,SUM(CASE WHEN k.loai_ky_thi=N'TOEIC' THEN 1 ELSE 0 END) toeic,SUM(CASE WHEN k.loai_ky_thi=N'IELTS' THEN 1 ELSE 0 END) ielts FROM m LEFT JOIN dbo.dang_ky_khoa_hoc dk ON dk.ngay_bat_dau>=m.d AND dk.ngay_bat_dau<DATEADD(MONTH,1,m.d) LEFT JOIN dbo.khoa_hoc k ON k.id=dk.ma_khoa_hoc GROUP BY m.d ORDER BY m.d OPTION(MAXRECURSION 24)`);res.json({data:r.recordset});});
router.get('/dashboard/role-distribution',async(_req,res)=>{const p=await getPool(),r=await p.request().query(`SELECT vai_tro,COUNT(*) value FROM dbo.nguoi_dung WHERE trang_thai<>N'da xoa' GROUP BY vai_tro`);const names={'quan tri vien':'Quản trị viên','giang vien':'Giảng viên','hoc vien':'Học viên'},colors={'quan tri vien':'#6366f1','giang vien':'#3b82f6','hoc vien':'#14b8a6'},total=r.recordset.reduce((s,x)=>s+x.value,0);res.json({data:r.recordset.map(x=>({name:names[x.vai_tro],value:x.value,color:colors[x.vai_tro],percentage:total?Math.round(x.value/total*100):0}))});});
router.get('/dashboard/recent-orders',async(_req,res)=>{const p=await getPool(),r=await p.request().query(`SELECT TOP (5) dh.ma_don_hang,dh.so_tien_phai_tra,dh.trang_thai,nd.ho_ten,(SELECT TOP 1 k.ten_khoa_hoc FROM dbo.chi_tiet_don_hang ct JOIN dbo.khoa_hoc k ON k.id=ct.ma_khoa_hoc WHERE ct.ma_don_hang=dh.ma_don_hang) course,g.ten_cong FROM dbo.don_hang dh JOIN dbo.nguoi_dung nd ON nd.id=dh.ma_hoc_vien OUTER APPLY(SELECT TOP 1 c.ten_cong FROM dbo.thanh_toan t JOIN dbo.cong_thanh_toan c ON c.ma_cong=t.ma_cong WHERE t.ma_don_hang=dh.ma_don_hang ORDER BY t.thoi_gian_tao DESC)g ORDER BY dh.ngay_tao DESC`);res.json({data:r.recordset.map(x=>({id:x.ma_don_hang,user:x.ho_ten,course:x.course||'—',amount:x.so_tien_phai_tra,status:orderStatusOut[x.trang_thai],paymentMethod:x.ten_cong||'—'}))});});
router.get('/dashboard/urgent-tickets',async(_req,res)=>{const p=await getPool(),r=await p.request().query(`SELECT TOP (5) yc.id,yc.tieu_de, yc.do_uu_tien,yc.trang_thai,yc.ngay_tao,nd.ho_ten FROM dbo.yeu_cau_ho_tro yc JOIN dbo.nguoi_dung nd ON nd.id=yc.nguoi_dung_id WHERE yc.do_uu_tien=N'cao' AND yc.trang_thai IN (N'moi',N'dang xu ly') ORDER BY yc.ngay_tao`);res.json({data:r.recordset.map(x=>({id:x.id,subject:x.tieu_de,requester:x.ho_ten,priority:'high',status:{moi:'new','dang xu ly':'in_progress'}[x.trang_thai],createdAt:x.ngay_tao}))});});
router.get('/dashboard/pending-reviews',async(_req,res)=>{const p=await getPool(),r=await p.request().query(`SELECT TOP (5) nd.ma_noi_dung id,nd.tieu_de title,k.loai_ky_thi category,nd.ngay_tao submittedAt,g.ho_ten author FROM dbo.noi_dung_khoa_hoc nd JOIN dbo.chuong_khoa_hoc c ON c.ma_chuong=nd.ma_chuong JOIN dbo.khoa_hoc k ON k.id=c.ma_khoa_hoc JOIN dbo.nguoi_dung g ON g.id=k.nguoi_tao_id WHERE nd.trang_thai_duyet=N'cho duyet' ORDER BY nd.ngay_tao`);res.json({data:r.recordset});});
export default router;
